from collections import defaultdict


def parse_query(query: str) -> dict[str, list[str]]:
    if not query:
        return {}

    if query.startswith("?"):
        query = query[1:]

    if not query:
        return {}

    def decode(s: str) -> str:
        s = s.replace("+", " ")
        if "%" not in s:
            return s

        i = 0
        n = len(s)
        byte_chunks = []
        res_parts = []

        while i < n:
            if s[i] == "%" and i + 2 < n:
                hex_digits = s[i + 1 : i + 3]
                try:
                    byte_val = int(hex_digits, 16)
                    byte_chunks.append(byte_val)
                    i += 3
                    continue
                except ValueError:
                    pass

            if byte_chunks:
                res_parts.append(bytes(byte_chunks).decode("utf-8", errors="replace"))
                byte_chunks = []

            res_parts.append(s[i])
            i += 1

        if byte_chunks:
            res_parts.append(bytes(byte_chunks).decode("utf-8", errors="replace"))

        return "".join(res_parts)

    result: dict[str, list[str]] = defaultdict(list)

    for piece in query.split("&"):
        if not piece:
            continue

        if "=" in piece:
            key, value = piece.split("=", 1)
        else:
            key, value = piece, ""

        decoded_key = decode(key)
        decoded_value = decode(value)

        result[decoded_key].append(decoded_value)

    return dict(result)
